package com.cyril.ecommerce.controller;
import com.cyril.ecommerce.dto.CheckoutRequest; import com.cyril.ecommerce.entity.*; import com.cyril.ecommerce.repository.*; import com.cyril.ecommerce.service.UserService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.util.*;
@RestController @RequestMapping("/api/orders") public class OrderController {private final OrderRepository orders;private final CartItemRepository cart;private final ProductRepository products;private final UserService users;public OrderController(OrderRepository orders,CartItemRepository cart,ProductRepository products,UserService users){this.orders=orders;this.cart=cart;this.products=products;this.users=users;} @PostMapping @Transactional public Order checkout(@Valid @RequestBody CheckoutRequest r){User u=users.current();List<CartItem> items=cart.findByUser(u);if(items.isEmpty())throw new IllegalArgumentException("Cart is empty");Order o=new Order(null,u,0.0,OrderStatus.PLACED,PaymentStatus.PENDING,r.shippingAddress(),LocalDateTime.now(),new ArrayList<>());double total=0;for(CartItem c:items){if(c.getQuantity()>c.getProduct().getStock())throw new IllegalArgumentException("Insufficient stock for "+c.getProduct().getName());Product p=c.getProduct();p.setStock(p.getStock()-c.getQuantity());products.save(p);OrderItem oi=new OrderItem(null,o,p,c.getQuantity(),p.getPrice());o.getItems().add(oi);total+=p.getPrice()*c.getQuantity();}o.setTotalAmount(total);Order saved=orders.save(o);cart.deleteByUser(u);return saved;} @GetMapping public List<Order> mine(){return orders.findByUserOrderByCreatedAtDesc(users.current());} @GetMapping("/{id}") public Order one(@PathVariable Long id){Order o=orders.findById(id).orElseThrow();if(!o.getUser().getId().equals(users.current().getId()))throw new IllegalArgumentException("Order not found");return o;}}
